def transform(grid):
    g=[r[:] for r in grid]
    h=len(g); w=len(g[0])
    for r in range(0,h,2):
        for c in range(w):
            if g[r][c]==3: g[r][c]=8
    centers=[]
    for r in range(1,h,2):
        centers.append([c for c in range(w) if g[r][c]==7])
        for c in range(w):
            if g[r][c]==7: g[r][c]=8
    for k,r in enumerate(range(0,h,2)):
        cs=(centers[k-1] if k>0 else [])+(centers[k] if k<len(centers) else [])
        for c in cs: g[r][c]=6
        prev=centers[k-1] if k>0 else []
        nex=centers[k] if k<len(centers) else []
        left=right=False
        if prev and not nex:
            left=right=True
            if r==h-1: left=False
        elif len(nex)<len(prev): left=right=True
        elif len(nex)==len(prev)==1:
            if nex[0]>prev[0]: left=True
            elif nex[0]<prev[0]: right=True
        if left:
            for c in range(w):
                if g[r][c]==8 and (c==0 or g[r][c-1]==0): g[r][c]=3
                elif g[r][c]==6: break
        if right:
            for c in range(w-1,-1,-1):
                if g[r][c]==8 and (c==w-1 or g[r][c+1]==0): g[r][c]=3
                elif g[r][c]==6: break
    return g

